auto func (auto value){  
    using T = decltype(value);  
    T sum = std::accumulate(std::begin(value), std::end(value), 0);  
    return std::make_pair(sum / value.size(), static_cast<T>(std::set<T>(value.begin(), value.end()).size()));  
}

auto func (auto value){ 
    std::set<decltype(value)> uniqueValues{value.begin(), value.end()};
    return std::make_pair(uniqueValues.size(), std::accumulate(value.begin(), value.end(), 0, [](int acc, const auto& v){return acc + (v != 0);}));
}
